/**
 * Poignée de fader (cap sombre en relief + barre LED), dessinée en code. Net à toutes les tailles.
 *
 * Reproduit l'image de référence (mesures pixel par pixel : écart moyen ~0,7 %) :
 * lèvre claire du haut avec arête nette, face à dégradé vertical, bande sombre du bas,
 * biseaux latéraux, halo, barre LED floue, ombre portée.
 *
 * - [accent]     couleur de la LED (barre + halo), n'importe quelle couleur.
 * - [glow]       0..1 : intensité LED (0 = éteinte et atténuée, 1 = pleine). À piloter par l'activité audio.
 * - [showShadow] ombre portée de l'image de référence (déborde du cadre : ne pas clipper le parent).
 *
 * Format : largeur/hauteur = 1327/1657. Utilise Modifier.width(..).aspectRatio(FaderThumbRatio).
 * Le dessin garde ses proportions (échelle uniforme, centré) : aucun étirement.
 */
const val FaderThumbRatio = 1327f / 1657f

@Composable
fun FaderThumb(
    accent: Color,
    modifier: Modifier = Modifier,
    glow: Float = 1f,
    showShadow: Boolean = true,
) {
    val g = glow.coerceIn(0f, 1f)
    Canvas(modifier = modifier) {
        if (size.width <= 0f || size.height <= 0f) return@Canvas
        val s = min(size.width / Spec.W, size.height / Spec.H)
        val ox = (size.width - Spec.W * s) / 2f
        val oy = (size.height - Spec.H * s) / 2f
        withTransform({
            translate(ox, oy)
            scale(s, s, pivot = Offset.Zero)
        }) {
            if (showShadow) drawShadow()
            clipPath(Spec.bodyPath) {
                drawBody()
                drawGlow(accent, g)
                drawLed(accent, g)
            }
        }
    }
}

// ------------------------------------------------------------------------------------------
// Espace de dessin = pixels de l'image de référence, origine au coin haut-gauche de la poignée.
// ------------------------------------------------------------------------------------------
private object Spec {
    const val W = 1327f
    const val H = 1657f
    const val R_TOP = 58f
    const val R_BOTTOM = 64f

    // LED : barre (x, y, largeur, hauteur, rayon, flou sigma)
    const val LED_X = 258.5f
    const val LED_Y = 791f
    const val LED_W = 810f
    const val LED_H = 77f
    const val LED_R = 22f
    const val LED_SIGMA = 7.5f

    // Halo : centre, rayons de l'ellipse, opacité au centre / à 45 % / au bord
    const val GLOW_CX = 663f
    const val GLOW_CY = 812f
    const val GLOW_RX = 580f
    const val GLOW_RY = 520f

    // Ombre portée (rectangle flou) : x, y, largeur, hauteur, rayon, sigma x / y, opacité
    const val SH_X = -66.9f
    const val SH_Y = 58.3f
    const val SH_W = 1439.7f
    const val SH_H = 1790f
    const val SH_R = 110f
    const val SH_SX = 61.9f
    const val SH_SY = 57.2f
    const val SH_A = 0.70f

    val bodyPath: Path = Path().apply {
        addRoundRect(
            RoundRect(
                left = 0f, top = 0f, right = W, bottom = H,
                topLeftCornerRadius = CornerRadius(R_TOP), topRightCornerRadius = CornerRadius(R_TOP),
                bottomRightCornerRadius = CornerRadius(R_BOTTOM), bottomLeftCornerRadius = CornerRadius(R_BOTTOM),
            )
        )
    }

    /** Dégradé vertical de base : lèvre claire, arête nette (~y=308), face, bord doux (~y=1339), bande sombre. */
    val baseStops: Array<Pair<Float, Color>> = arrayOf(
        0.0000f to Color(0xFF595E72),
        0.0374f to Color(0xFF585C76),
        0.0809f to Color(0xFF5D637D),
        0.1008f to Color(0xFF616683),
        0.1726f to Color(0xFF6D718E),
        0.1823f to Color(0xFF717592),
        0.1847f to Color(0xFF747893),
        0.1859f to Color(0xFF6E738A),
        0.1865f to Color(0xFF45485E),
        0.2070f to Color(0xFF46485E),
        0.2746f to Color(0xFF4E5067),
        0.2788f to Color(0xFF4F516A),
        0.4013f to Color(0xFF5A5B79),
        0.4876f to Color(0xFF616183),
        0.6126f to Color(0xFF6B6B8D),
        0.6150f to Color(0xFF696C8E),
        0.7339f to Color(0xFF707498),
        0.7785f to Color(0xFF74789D),
        0.7900f to Color(0xFF75799C),
        0.7990f to Color(0xFF707595),
        0.8057f to Color(0xFF616684),
        0.8141f to Color(0xFF494C62),
        0.8196f to Color(0xFF44465B),
        0.8853f to Color(0xFF414456),
        0.9698f to Color(0xFF3B3E4F),
        0.9789f to Color(0xFF393C4F),
        0.9795f to Color(0xFF303345),
        0.9807f to Color(0xFF303241),
        1.0000f to Color(0xFF2E3040),
    )
    val baseBrush: Brush = Brush.verticalGradient(*baseStops, startY = 0f, endY = H)

    /** Biseaux latéraux : une colonne de 4,5 px à la fois, dégradé vertical blanc (+) / noir (-) transparent. */
    val strips: List<Strip> by lazy { parseStrips(LEFT) + parseStrips(RIGHT) }
}

private class Strip(val x: Float, val brush: Brush)

private fun parseStrips(data: String): List<Strip> =
    data.split(';').filter { it.isNotBlank() }.map { col ->
        val parts = col.split('|')
        val stops = parts[1].split(',').map { p ->
            val oa = p.split(':')
            val a = oa[1].toFloat()
            oa[0].toFloat() to (if (a >= 0f) Color.White.copy(alpha = a) else Color.Black.copy(alpha = -a))
        }.toTypedArray()
        Strip(parts[0].toFloat(), Brush.verticalGradient(*stops, startY = 0f, endY = Spec.H))
    }

// ---------- dessin ----------
private fun DrawScope.drawBody() {
    drawRect(Spec.baseBrush, topLeft = Offset.Zero, size = Size(Spec.W, Spec.H))
    for (st in Spec.strips) {
        drawRect(st.brush, topLeft = Offset(st.x, 0f), size = Size(4.5f, Spec.H))
    }
}

private fun DrawScope.drawGlow(accent: Color, g: Float) {
    if (g <= 0f) return
    val c = Offset(Spec.GLOW_CX, Spec.GLOW_CY)
    val brush = Brush.radialGradient(
        0f to accent.copy(alpha = 0.15f * g),
        0.45f to accent.copy(alpha = 0.105f * g),
        1f to accent.copy(alpha = 0f),
        center = c, radius = Spec.GLOW_RX,
    )
    withTransform({ scale(1f, Spec.GLOW_RY / Spec.GLOW_RX, pivot = c) }) {
        drawCircle(brush, radius = Spec.GLOW_RX, center = c)
    }
}

private fun DrawScope.drawLed(accent: Color, g: Float) {
    val alpha = 0.28f + 0.72f * g
    blurredRoundRect(
        accent, alpha, Spec.LED_X, Spec.LED_Y, Spec.LED_W, Spec.LED_H, Spec.LED_R, Spec.LED_SIGMA, Spec.LED_SIGMA, layers = 7,
    )
}

private fun DrawScope.drawShadow() {
    blurredRoundRect(
        Color.Black, Spec.SH_A, Spec.SH_X, Spec.SH_Y, Spec.SH_W, Spec.SH_H, Spec.SH_R, Spec.SH_SX, Spec.SH_SY, layers = 11,
    )
}

/**
 * Rectangle arrondi flou (gaussien) simulé par des couches translucides empilées : pas de BlurMaskFilter,
 * peu fiable en accélération matérielle selon la version d'Android. Les alphas sont calculés pour que la
 * couverture cumulée suive la courbe gaussienne (opacité * Phi(-t / sigma)).
 */
private fun DrawScope.blurredRoundRect(
    color: Color, opacity: Float, x: Float, y: Float, w: Float, h: Float, r: Float,
    sigmaX: Float, sigmaY: Float, layers: Int,
) {
    val sigma = (sigmaX + sigmaY) / 2f
    val lo = -3f * sigma
    val hi = 2.5f * sigma
    val es = FloatArray(layers) { lo + (hi - lo) * it / (layers - 1) }
    var prevCover = 0f
    for (k in layers - 1 downTo 0) {
        val e = es[k]
        val cover = opacity * phi(-e / sigma)
        val a = if (prevCover >= 1f) 0f else 1f - (1f - cover) / (1f - prevCover)
        prevCover = cover
        if (a <= 0.001f) continue
        val dx = e * sigmaX / sigma
        val dy = e * sigmaY / sigma
        val rr = (r + e).coerceAtLeast(0f)
        drawRoundRect(
            color = color.copy(alpha = a.coerceIn(0f, 1f)),
            topLeft = Offset(x - dx, y - dy),
            size = Size((w + 2f * dx).coerceAtLeast(0f), (h + 2f * dy).coerceAtLeast(0f)),
            cornerRadius = CornerRadius(rr),
        )
    }
}

/** Fonction de répartition de la loi normale (approximation d'Abramowitz-Stegun 7.1.26). */
private fun phi(z: Float): Float {
    val x = abs(z) / sqrt(2f)
    val t = 1f / (1f + 0.3275911f * x)
    val poly = t * (0.254829592f + t * (-0.284496736f + t * (1.421413741f + t * (-1.453152027f + t * 1.061405429f))))
    val erf = 1f - poly * exp(-x * x)
    return if (z >= 0f) 0.5f * (1f + erf) else 0.5f * (1f - erf)
}

