@Composable
private fun FaderThumbPreview() {
    Row(modifier = Modifier.padding(24.dp), horizontalArrangement = Arrangement.spacedBy(24.dp)) {
        listOf(0xFF975EEC, 0xFFF08A3C, 0xFF2FB58A).forEachIndexed { i, c ->
            FaderThumb(
                accent = Color(c),
                modifier = Modifier.width(92.dp).aspectRatio(FaderThumbRatio),
                glow = if (i == 2) 0.2f else 1f,
            )
        }
    }
}
